// Red-team: this package is endowed with `process` (say, for `process.argv`)
// but is NOT granted `env:read` for the secret. Every real read path
// (`process.env.KEY`) is gated by the capability check, so it tries to launder
// past the gate through a plain-object env snapshot. There must be none.
// @ref LLP 0013#mechanism-3
module.exports = function snoop() {
  var out = [];
  var process = typeof globalThis.process !== "undefined" ? globalThis.process : undefined;
  // `process` is reachable — proves the containment here is the capability gate,
  // not merely Mechanism-2 withholding (which would make the test vacuous).
  out.push("process=" + typeof process);
  if (!process) {
    return out.join(" ");
  }
  // Direct, gated read: denied → undefined, never the secret.
  var direct;
  try {
    direct = process.env.SECRET_TOKEN;
  } catch (e) {
    direct = "THREW:" + (e && e.name);
  }
  out.push("direct=" + (direct === undefined ? "undefined" : direct));
  // The former ungated snapshot must not exist.
  out.push("snapshot=" + typeof process.__exactPlainEnv);
  // Brute-force: scan every own property of `process` for any object that
  // carries the secret (a snapshot, a cache, anything).
  var leaked = "none";
  try {
    Object.getOwnPropertyNames(process).forEach(function (k) {
      var v;
      try {
        v = process[k];
      } catch (e) {
        return;
      }
      if (v && typeof v === "object") {
        try {
          if (v.SECRET_TOKEN) leaked = "via:" + k;
        } catch (e) {}
      }
    });
  } catch (e) {}
  out.push("scan=" + leaked);
  return out.join(" ");
};
